<?php require_once 'includes/../includes/header.php'; $error=''; $categories=$pdo->query('SELECT * FROM categories ORDER BY category_name')->fetchAll(); if($_SERVER['REQUEST_METHOD']==='POST'){ $name=trim($_POST['food_name']??'');$description=trim($_POST['description']??'');$category=(int)($_POST['category_id']??0);$price=(float)($_POST['price']??0);$image=trim($_POST['image']??'');$availability=isset($_POST['availability'])?1:0; if(!$name||!$description||!$category||$price<=0||!filter_var($image,FILTER_VALIDATE_URL))$error='Please complete the fields and use a valid image URL.'; else{$stmt=$pdo->prepare('INSERT INTO foods(category_id,food_name,description,price,image,availability) VALUES(?,?,?,?,?,?)');$stmt->execute([$category,$name,$description,$price,$image,$availability]);redirect('foods.php');}} $page_title='Add Food'; ?><div class="form-shell"><h1>Add food</h1><?php if($error): ?><p class="error"><?=esc($error)?></p><?php endif; ?><form method="post"><label>Food name<input name="food_name" required></label><label>Category<select name="category_id" required><option value="">Choose category</option><?php foreach($categories as $category): ?><option value="<?=$category['id']?>"><?=esc($category['category_name'])?></option><?php endforeach; ?></select></label><label>Description<textarea name="description" required></textarea></label><label>Price<input type="number" name="price" min="1" step="0.01" required></label><label>Image URL<input type="url" name="image" placeholder="https://..." required></label><label><input type="checkbox" name="availability" checked style="width:auto"> Available</label><button type="submit">Save Food</button> <a class="button secondary" href="foods.php">Cancel</a></form></div><?php include 'includes/footer.php'; ?>